                if (cfg.jira.statuses) {
                    for (var st in cfg.jira.statuses) {
                        if (cfg.jira.statuses.hasOwnProperty(st)) {
                            result.jira.statuses[st] = cfg.jira.statuses[st];
                        }
                    }
                }
            }
            return result;
        }
    };
}

