            '      - run: |',
            '          env: stuffing',
            '          fake_key: nope',
            '      - run: echo done'
        ].join('\n');
        assert.deepEqual(lint.findDuplicateKeys(yml), []);
    });

    test('folded scalar (run-name: >-) content never produces keys', function () {
        var yml = [
            'run-name: >-',
