var REF_PAT = /(agents\/)?((?:instructions|js)\/[A-Za-z0-9_\-./]+\.(?:md|js))/g;

// Repo root, resolved once from file_list('..') absolute entries (relative
// '../x' resolves against the job's working directory, not the test cwd —
