            github_update_check_run: function (args) {
                seen.push(args.conclusion);
                return '{}';
            }
        });

        var summary = ci.stampRequiredChecks(baseOpts());

        assert.deepEqual(seen, ['success']);
        assert.equal(summary.stamped[0].checkRunId, 5);
    });

