/**
 * Unit tests for workflows/ai-teammate.yml.template (the per-repo AI
 * Teammate stub the target repos copy).
 *
 * Owner 2026-09-27 (live: dmd run 36333172145): a PR-anchored SM dispatch
 * (#544/#687 — inputs.pr set, inputs.issue empty) titled the run
 * '▶ rework (SM) · gh-\n· gh-: ' — the template rendered the 'gh-' prefix
 * with an empty scraped number. The run-name must carry the EFFECTIVE
 * anchor: pr-<N> after the fallback, gh-<N> when the issue anchor is real.
 */
'use strict';

suite('ai-teammate.yml.template — run-name carries the effective anchor', function () {

    var tpl = file_read({ path: 'workflows/ai-teammate.yml.template' });

    test('run-name renders pr-<N> when inputs.pr is set (PR-anchored fallback, #544/#687)', function () {
        assert.ok(tpl.indexOf("format('pr-{0}', github.event.inputs.pr)") !== -1,
            "run-name must format the PR anchor as pr-<N>");
        assert.ok(tpl.indexOf("(github.event.inputs.pr || '') != ''") !== -1,
            'null-safe pr guard — on label events inputs are null and null != \'\' would be TRUE');
        assert.ok(tpl.indexOf("format('▶ {0} (SM) · {1}'") !== -1,
            'the SM-dispatch title line takes the effective anchor as its second format arg');
    });

    test('run-name no longer renders a bare gh- prefix off the empty issue input', function () {
        assert.ok(tpl.indexOf("format('▶ {0} (SM) · gh-{1}', github.event.inputs.leg, github.event.inputs.issue)") === -1,
            'the malformed legacy template is gone — no gh- prefix off inputs.issue');
        assert.ok(tpl.indexOf("github.event.issue.number || github.event.inputs.issue") !== -1,
            'issue events keep the gh-<issue.number> anchor');
        assert.ok(tpl.indexOf("github.event.issue.title && format(': {0}', github.event.issue.title)") !== -1,
            "': <title>' renders only when an issue title exists (no trailing ': ' on PR-anchored runs)");
    });

    test('the dispatch contract declares the pr input (optional string, #687)', function () {
        var prDecl = tpl.indexOf('pr:');
        assert.ok(prDecl !== -1, 'pr input declared');
        assert.ok(tpl.indexOf("description: 'PR number for PR-anchored runs") !== -1,
            'pr input documented');
        assert.ok(tpl.indexOf("required: true,\n        type: number") === -1,
            'issue is no longer a required number — PR-anchored dispatches send an empty issue');
    });

    test('concurrency group keeps PR-anchored runs per-PR', function () {
        assert.ok(tpl.indexOf("format('pr-{0}', github.event.inputs.pr) }}") !== -1,
            'empty issue falls back to pr-<N> in the concurrency group — PR-anchored runs must not share one global group');
    });
});

/**
 * Unit tests: ci.js — required check-run mirroring for dispatch-only runs.
 *
 * Covered: happy path (create + update with the real conclusion),
 * skipped job never stamped, not-completed job never stamped, missing
 * job reported, duplicate job names resolve to the last attempt,
 * commit-status fallback mapping, empty runId rejected, empty
 * requiredChecks is a no-op, jobName override.
 */
/* global loadModule, assert, test, suite */

suite('ci stampRequiredChecks', function () {

    var RUN_JOBS = {
        total_count: 4,
        jobs: [
            { id: 11, name: 'gate', status: 'completed', conclusion: 'success', html_url: 'https://ci/run/1/job/11' },
            { id: 12, name: 'agents-suite', status: 'completed', conclusion: 'failure', html_url: 'https://ci/run/1/job/12' },
            { id: 13, name: 'docs', status: 'completed', conclusion: 'skipped', html_url: 'https://ci/run/1/job/13' },
            { id: 14, name: 'lint', status: 'in_progress', conclusion: null, html_url: 'https://ci/run/1/job/14' }
        ]
    };

    function loadCi(mocks) {
        return loadModule('js/common/ci.js', makeRequire({}, mocks || {}), mocks || {});
    }

    function baseOpts(overrides) {
        var opts = {
            workspace: 'epam',
            repository: 'dmtools-dart',
            headSha: 'abc123',
            runId: 36001952519,
            requiredChecks: [{ name: 'gate' }]
        };
        if (overrides) {
            for (var k in overrides) opts[k] = overrides[k];
        }
        return opts;
    }

    test('happy path stamps the real conclusion via create + update', function () {
        var calls = [];
        var ci = loadCi({
            github_get_workflow_run_jobs: function () { return JSON.stringify(RUN_JOBS); },
            github_create_check_run: function (args) {
                calls.push({ step: 'create', args: args });
                return JSON.stringify({ id: 9001 });
            },
            github_update_check_run: function (args) {
                calls.push({ step: 'update', args: args });
                return '{}';
            }
        });

        var summary = ci.stampRequiredChecks(baseOpts({
            requiredChecks: [{ name: 'gate' }, { name: 'agents-suite' }]
        }));

        assert.equal(calls.length, 4);
        assert.equal(calls[0].step, 'create');
        assert.equal(calls[0].args.name, 'gate');
        assert.equal(calls[0].args.headSha, 'abc123');
        assert.equal(calls[1].step, 'update');
        assert.equal(calls[1].args.checkRunId, 9001);
        assert.equal(calls[1].args.conclusion, 'success');
        assert.equal(calls[3].args.conclusion, 'failure');
        assert.equal(summary.stamped.length, 2);
        assert.equal(summary.stamped[0].name, 'gate');
        assert.equal(summary.stamped[0].conclusion, 'success');
        assert.equal(summary.stamped[1].conclusion, 'failure');
        assert.deepEqual(summary.skipped, []);
        assert.deepEqual(summary.missing, []);
    });

    test('update summary links back to the source run job', function () {
        var ci = loadCi({
            github_get_workflow_run_jobs: function () { return JSON.stringify(RUN_JOBS); },
            github_create_check_run: function () { return JSON.stringify({ id: 1 }); },
            github_update_check_run: function (args) {
                assert.ok(args.summary.indexOf('workflow run 36001952519') !== -1);
                assert.ok(args.summary.indexOf('job/11') !== -1);
                return '{}';
            }
        });
        ci.stampRequiredChecks(baseOpts());
    });

    test('skipped job is never stamped', function () {
        var created = 0;
        var ci = loadCi({
            github_get_workflow_run_jobs: function () { return JSON.stringify(RUN_JOBS); },
            github_create_check_run: function () { created += 1; return JSON.stringify({ id: 1 }); },
